-- wisegraph: Wiser's people/tradition graph (the funnygraph equivalent), mirrored from wisegraph/*.json.
-- Seed/refresh: npx wrangler d1 execute wiser --remote --file ../wisegraph/seed.sql (generated by tools/build-clips.py)
CREATE TABLE IF NOT EXISTS wg_traditions (
  id TEXT PRIMARY KEY, label TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('family', 'school', 'lineage')),
  parent TEXT, wikidata TEXT
);
CREATE TABLE IF NOT EXISTS wg_people (
  id TEXT PRIMARY KEY, name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('speaker', 'figure', 'text')), -- speaker = on video; figure/text = sources met through talks about them
  tradition TEXT NOT NULL, wikidata TEXT, years TEXT, bio TEXT
);
CREATE INDEX IF NOT EXISTS wg_people_tradition ON wg_people (tradition);
CREATE TABLE IF NOT EXISTS wg_works ( -- the 'specials': books, talk series, retreats, texts
  id TEXT NOT NULL, person TEXT NOT NULL, title TEXT NOT NULL, year INTEGER, kind TEXT,
  PRIMARY KEY (id, person)
);
CREATE TABLE IF NOT EXISTS wg_edges ( -- teacher_of | influenced | lineage_of; src/dst are person or tradition ids
  src TEXT NOT NULL, dst TEXT NOT NULL, type TEXT NOT NULL, conf TEXT, note TEXT
);
CREATE INDEX IF NOT EXISTS wg_edges_src ON wg_edges (src);
CREATE INDEX IF NOT EXISTS wg_edges_dst ON wg_edges (dst);
CREATE TABLE IF NOT EXISTS wg_clip_links ( -- a clip -> its speaker, the figures and traditions it discusses, its topics
  clip TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('speaker', 'figure', 'tradition', 'topic')), ref TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS wg_clip_links_ref ON wg_clip_links (kind, ref);
CREATE INDEX IF NOT EXISTS wg_clip_links_clip ON wg_clip_links (clip);
